import org.eclipse.rdf4j.sail.backup.SailBackupService;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class LmdbBackupMetadataTest {

	@TempDir
	Path directory;

	private final ValueFactory vf = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@CsvSource({ "2,NONE", "2,ZIP", "6,NONE", "6,ZIP" })
	void preservesPersistedMetadataAcrossSnapshotBackupAndRestore(int version, BackupCompression compression)
			throws Exception {
		Path source = Files.createDirectory(directory.resolve("store"));
		if (version == LmdbStoreFormat.LEGACY_VERSION) {
			// Select the legacy writer before creating either native environment, never relabel format-6 IDs.
			new StoreProperties(source.toFile()).setVersion("2")
					.setTripleIndexes("spoc,posc")
					.setTripleTermIndexes("spoc,cspo")
					.save();
		}
		LmdbStore store = new LmdbStore(source.toFile(), config());
		store.init();
		try {
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				for (Literal literal : literals()) {
					connection.addStatement(vf.createIRI("urn:metadata:subject"),
							vf.createIRI("urn:metadata:predicate"), literal);
				}
				connection.commit();
			}
			Files.writeString(source.resolve(StoreProperties.FILE_NAME),
					"\n# Preserve owner comments and unknown properties verbatim\nexternal-owner.setting=retained\n",
					StandardOpenOption.APPEND);
			byte[] original = Files.readAllBytes(source.resolve(StoreProperties.FILE_NAME));
			assertFormat(source, version);
			Path snapshot = directory.resolve("snapshot");
			store.getBackingStore().createOnlineSnapshot(snapshot, true, () -> {
			});
			assertMetadata(snapshot, original, version);

			SailBackupService service = store.getBackupService();
			Path backups = directory.resolve("backups");
			BackupResult backup = service.createBackup(BackupRequest.builder(backups, BackupType.FULL)
					.compression(compression)
					.build());
			assertThat(service.verify(backup)).isTrue();
			assertMetadata(source, original, version);
			if (compression == BackupCompression.ZIP) {
				try (ZipFile zip = new ZipFile(backup.getArtifactPath().toFile())) {
					try (var input = zip.getInputStream(zip.getEntry(StoreProperties.FILE_NAME))) {
						assertThat(input.readAllBytes()).isEqualTo(original);
					}
				}
			} else {
				assertMetadata(backup.getArtifactPath(), original, version);
			}
			Path restored = service.restore(new PointInTimeRestoreRequest(backups,
					directory.resolve("restored"), backup.getEndTransactionId(), true));
			assertMetadata(restored, original, version);
			assertReadable(restored, version);
			assertMetadata(restored, original, version);
			assertMetadata(source, original, version);
		} finally {
			store.shutDown();
		}
	}

	private void assertReadable(Path path, int version) {
		LmdbStore restored = new LmdbStore(path.toFile(), config());
		restored.init();
		try {
			assertThat(restored.getFormat().getVersion()).isEqualTo(version);
			try (SailConnection connection = restored.getConnection()) {
				assertThat(connection.size()).isEqualTo(literals().size());
				for (Literal literal : literals()) {
					assertThat(connection.hasStatement(vf.createIRI("urn:metadata:subject"),
							vf.createIRI("urn:metadata:predicate"), literal, false)).isTrue();
				}
			}
		} finally {
			restored.shutDown();
		}
	}

	private void assertMetadata(Path path, byte[] original, int version) throws Exception {
		assertThat(Files.readAllBytes(path.resolve(StoreProperties.FILE_NAME))).isEqualTo(original);
		assertFormat(path, version);
	}

	private void assertFormat(Path path, int version) {
		StoreProperties properties = new StoreProperties(path.toFile());
		assertThat(properties.load()).isTrue();
		assertThat(properties.getRawProperty("external-owner.setting")).isEqualTo("retained");
		LmdbStoreFormat format = LmdbStoreFormat.resolve(path.toFile(), properties, config());
		boolean current = version == LmdbStoreFormat.CURRENT_VERSION;
		assertThat(format.getVersion()).isEqualTo(version);
		assertThat(format.inlinesLiterals()).isTrue();
		assertThat(format.usesOrderedNumericIds()).isEqualTo(current);
		assertThat(format.usesCoreDatatypeLiteralReferences()).isEqualTo(current);
		assertThat(format.usesCanonicalLanguageTags()).isEqualTo(current);
		assertThat(format.usesZeroFractionDateTimeIds()).isEqualTo(current);
		if (!current) {
			assertThat(properties.getRawProperty(StoreProperties.INLINE_LITERALS_KEY)).isNull();
		}
	}

	private List<Literal> literals() {
		return List.of(vf.createLiteral("persisted dictionary literal"), vf.createLiteral("language", "eN-GB"),
				vf.createLiteral("2026-10-02T12:37:00.000Z", XSD.DATETIME), vf.createLiteral(-37));
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(true)
				.setOrderedNumericIds(true);
	}
}
